# Analyzing the pattern from the demo
# Input is 16x18 with 7s as background, 3s as centers
# Output has 1s in 3x3 regions around each 3, except the center stays 3

# The transformation rule per cell:
# 1. If input[r,c] == 3: output[r,c] = 3
# 2. If any 3x3 block centered on an input 3 covers (r,c): output[r,c] = 1
# 3. Otherwise: output[r,c] = 7 (or keeps original val)

# For the test 5x9 grid:
# Background = 7, "centers" = 2

# The rule should be similar:
# - Each 2 at (r,c) creates a 3x3 region of 1s (or 7s) except center stays 2
# - Check which cells in output are covered by at least one 3x3 around input 2

test_input = [
    [2, 7, 2, 7, 2, 2, 7, 2, 7],
    [7, 7, 2, 7, 7, 7, 7, 2, 2],
    [7, 2, 7, 2, 7, 7, 7, 7, 2],
    [2, 7, 2, 7, 2, 7, 2, 2, 2],
    [7, 7, 7, 7, 7, 2, 7, 7, 7]
]

rows, cols = len(test_input), len(test_input[0])

# Build output
output = [[None]*cols for _ in rows]

# Step 1: All 2s stay
for r in range(rows):
    for c in range(cols):
        if test_input[r][c] == 2:
            output[r][c] = 2
        else:
            output[r][c] = None  # Will fill later if covered

# Step 2: 3x3 expansion around each 2
