        if test_input[r][c] == 2:
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < rows and 0 <= nc < cols:
                        # Mark position with 1 if not already set
                        if output[nr][nc] is None:
                            output[nr][nc] = 1

# Final: remaining None positions should be ?
for r in range(rows):
    for c in range(cols):
        if output[r][c] is None:
            output[r][c] = 2  # Default from observed pattern

# But wait - None cells might need different treatment
# Let me check if there should be gap analysis
